import React, { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { motion } from 'framer-motion'
import { useAuthStore } from '@/stores/authStore'
import { useThemeStore } from '@/stores/themeStore'
import { useLanguageStore } from '@/stores/languageStore'
import { Activity, ArrowRight, CheckCircle2, Globe2, Lock, Mail, Moon, Radar, Shield, Sparkles, Sun, Eye, EyeOff, Fingerprint, Gauge, Network, KeyRound } from 'lucide-react'
import { cn } from '@/utils/cn'

const loginSchema = z.object({ email: z.string().email('البريد الإلكتروني غير صحيح'), password: z.string().min(8, 'كلمة المرور يجب أن تكون 8 أحرف على الأقل'), rememberMe: z.boolean().optional() })
type LoginForm = z.infer<typeof loginSchema>

export const Login = () => {
  const navigate = useNavigate(); const { login } = useAuthStore(); const { resolvedTheme, toggleTheme } = useThemeStore(); const { language, setLanguage } = useLanguageStore()
  const [showPassword, setShowPassword] = useState(false); const [loading, setLoading] = useState(false); const [otp, setOtp] = useState(''); const [twoFactorRequired, setTwoFactorRequired] = useState(false)
  const { register, handleSubmit, formState: { errors } } = useForm<LoginForm>({ resolver: zodResolver(loginSchema), defaultValues: { rememberMe: true } })
  const onSubmit = async (data: LoginForm) => {
    setLoading(true)
    try {
      await login(data.email, data.password, data.rememberMe, twoFactorRequired ? otp : undefined)
      toast.success('مرحباً بك في AegisScan'); navigate('/dashboard')
    } catch (error: any) {
      const requiresOtp = Boolean(error?.response?.data?.two_factor_required)
      if (requiresOtp) { setTwoFactorRequired(true); setOtp(''); toast.info('أدخل رمز التحقق بخطوتين للمتابعة') }
      else toast.error(error.response?.data?.error?.message || error.response?.data?.detail || 'فشل تسجيل الدخول')
    } finally { setLoading(false) }
  }

  return <div className="min-h-screen overflow-hidden bg-background lg:grid lg:grid-cols-[1.12fr_.88fr]">
    <section className="relative hidden min-h-screen overflow-hidden border-r border-white/10 bg-[#07111f] p-8 text-white lg:flex lg:flex-col lg:justify-between xl:p-12">
      <div className="pointer-events-none absolute inset-0 opacity-[.16] [background-image:linear-gradient(rgba(148,163,184,.18)_1px,transparent_1px),linear-gradient(90deg,rgba(148,163,184,.18)_1px,transparent_1px)] [background-size:44px_44px]" />
      <div className="pointer-events-none absolute -left-20 top-20 h-[520px] w-[520px] rounded-full bg-primary/20 blur-[120px]" /><div className="pointer-events-none absolute bottom-0 right-0 h-[420px] w-[420px] rounded-full bg-cyan-500/10 blur-[110px]" />
      <div className="pointer-events-none absolute left-1/2 top-1/2 h-[620px] w-[620px] -translate-x-1/2 -translate-y-1/2 rounded-full border border-white/10" /><div className="pointer-events-none absolute left-1/2 top-1/2 h-[430px] w-[430px] -translate-x-1/2 -translate-y-1/2 rounded-full border border-primary/20" />
      <div className="relative flex items-center justify-between"><div className="flex items-center gap-3"><span className="aegis-ring grid h-12 w-12 place-items-center rounded-2xl border border-white/15 bg-white/10"><Shield className="h-5 w-5" /></span><div><div className="text-xl font-black tracking-tight">AegisScan</div><div className="text-[10px] uppercase tracking-[.22em] text-white/45">Security Assurance Platform</div></div></div><div className="flex items-center gap-2 rounded-full border border-emerald-400/20 bg-emerald-400/10 px-3 py-1.5 text-[10px] font-bold tracking-wider text-emerald-300"><span className="aegis-live-dot" /> ENTERPRISE</div></div>
      <div className="relative max-w-2xl"><motion.div initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} className="mb-5 inline-flex items-center gap-2 rounded-full border border-primary/20 bg-primary/10 px-3 py-1.5 text-xs font-semibold text-primary-foreground"><Sparkles className="h-3.5 w-3.5" /> Continuous security validation</motion.div><motion.h1 initial={{opacity:0,y:22}} animate={{opacity:1,y:0}} transition={{delay:.08}} className="text-5xl font-black leading-[1.02] tracking-[-.045em] xl:text-[4.35rem]">See the risk.<br /><span className="text-white/70">Prove the fix.</span><br />Control the outcome.</motion.h1><motion.p initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{delay:.16}} className="mt-7 max-w-xl text-base leading-7 text-white/55">Investigate attack paths, correlate evidence, measure remediation, and turn security signals into confident executive decisions.</motion.p>
        <div className="mt-9 grid max-w-xl grid-cols-3 gap-3"><Signal label="Validation engines" value="15+" icon={<Radar className="h-4 w-4" />} /><Signal label="Assurance layers" value="10+" icon={<Network className="h-4 w-4" />} /><Signal label="Evidence driven" value="E2E" icon={<CheckCircle2 className="h-4 w-4" />} /></div>
        <div className="mt-5 grid max-w-xl grid-cols-2 gap-3"><MiniStatus icon={<Gauge className="h-4 w-4" />} title="Security posture" value="Continuously monitored" /><MiniStatus icon={<Fingerprint className="h-4 w-4" />} title="Evidence integrity" value="Auditable by design" /></div>
      </div>
      <div className="relative flex items-center justify-between text-[10px] font-medium tracking-wide text-white/35"><span>Continuous Assurance Fabric</span><span>Protected · Auditable · Evidence-backed</span></div>
    </section>

    <section className="relative flex min-h-screen items-center justify-center overflow-hidden p-5 sm:p-8"><div className="pointer-events-none absolute right-0 top-0 h-96 w-96 rounded-full bg-primary/8 blur-[100px]" /><div className="relative w-full max-w-[440px]">
      <div className="mb-8 flex items-center justify-between"><div className="flex items-center gap-2 lg:hidden"><span className="aegis-ring grid h-9 w-9 place-items-center rounded-xl border bg-muted"><Shield className="h-4 w-4 text-primary" /></span><span className="font-black">AegisScan</span></div><div className="ml-auto flex items-center gap-2"><button onClick={() => setLanguage(language === 'ar' ? 'en' : 'ar')} className="aegis-focus-visible rounded-xl border bg-muted/50 px-3 py-2 text-xs font-semibold transition hover:bg-muted">{language === 'ar' ? 'English' : 'العربية'}</button><button onClick={toggleTheme} className="aegis-focus-visible rounded-xl border bg-muted/50 p-2 hover:bg-muted" aria-label="Toggle theme">{resolvedTheme === 'dark' ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button></div></div>
      <div className="mb-7"><div className="mb-4 inline-flex items-center gap-2 rounded-full border border-emerald-500/20 bg-emerald-500/8 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400"><span className="aegis-live-dot" /> Secure access</div><h2 className="text-3xl font-black tracking-[-.035em]">{twoFactorRequired ? 'تحقق بخطوتين' : 'مرحبًا بعودتك'}</h2><p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">{twoFactorRequired ? 'أدخل الرمز المؤقت من تطبيق المصادقة لإكمال تسجيل الدخول.' : 'سجّل الدخول إلى مركز التحقيق والضمان الأمني في AegisScan.'}</p></div>
      <form onSubmit={handleSubmit(onSubmit)} className="aegis-surface aegis-surface-hover rounded-3xl p-5 shadow-xl sm:p-7">
        <div className="mb-5 flex items-center gap-3 rounded-2xl border bg-muted/30 p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 text-primary"><Lock className="h-4 w-4" /></div><div><div className="text-xs font-bold">Protected workspace</div><div className="text-[10px] text-muted-foreground">RBAC · Audit trail · Evidence-first</div></div></div>
        <div className="space-y-5">
        {!twoFactorRequired ? <><Field label="البريد الإلكتروني" error={errors.email?.message}><div className="relative"><Mail className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input {...register('email')} id="email" type="email" autoComplete="email" placeholder="user@company.com" disabled={loading} className={cn('aegis-focus-visible w-full rounded-xl border bg-background/70 py-3.5 pl-11 pr-4 text-sm outline-none transition placeholder:text-muted-foreground/55 focus:border-primary focus:ring-4 focus:ring-primary/10', errors.email && 'border-destructive')} /></div></Field>
        <Field label="كلمة المرور" error={errors.password?.message}><div className="relative"><Lock className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input {...register('password')} id="password" type={showPassword ? 'text' : 'password'} autoComplete="current-password" placeholder="••••••••" disabled={loading} className={cn('aegis-focus-visible w-full rounded-xl border bg-background/70 py-3.5 pl-11 pr-12 text-sm outline-none transition placeholder:text-muted-foreground/55 focus:border-primary focus:ring-4 focus:ring-primary/10', errors.password && 'border-destructive')} /><button type="button" onClick={() => setShowPassword(v=>!v)} className="aegis-focus-visible absolute right-3 top-1/2 -translate-y-1/2 rounded-lg p-1 text-muted-foreground hover:text-foreground" aria-label={showPassword ? 'إخفاء كلمة المرور' : 'إظهار كلمة المرور'}>{showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}</button></div></Field>
        <div className="flex items-center justify-between gap-3"><label className="flex items-center gap-2 text-sm text-muted-foreground"><input {...register('rememberMe')} type="checkbox" className="h-4 w-4 rounded border-border text-primary focus:ring-primary" />تذكرني</label><Link to="/forgot-password" className="aegis-focus-visible rounded text-xs font-bold text-primary hover:underline">نسيت كلمة المرور؟</Link></div></> : <div><label htmlFor="otp" className="mb-2 block text-xs font-bold">رمز التحقق</label><div className="relative"><KeyRound className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input id="otp" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} inputMode="numeric" autoComplete="one-time-code" maxLength={6} placeholder="000000" disabled={loading} autoFocus className="aegis-focus-visible w-full rounded-xl border bg-background/70 py-4 pl-11 pr-4 text-center text-xl font-black tracking-[.4em] outline-none focus:border-primary focus:ring-4 focus:ring-primary/10" /><p className="mt-2 text-xs text-muted-foreground">الرمز صالح لفترة قصيرة. لا تشاركه مع أي شخص.</p></div><button type="button" onClick={()=>{setTwoFactorRequired(false);setOtp('')}} className="mt-3 text-xs font-semibold text-primary hover:underline">العودة وإعادة إدخال بيانات الدخول</button></div>}
        <button type="submit" disabled={loading || (twoFactorRequired && otp.length !== 6)} className="group flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 font-bold text-primary-foreground shadow-lg shadow-primary/20 transition duration-200 hover:-translate-y-0.5 hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-60">{loading ? <><span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground/30 border-t-primary-foreground" /> جاري التحقق...</> : twoFactorRequired ? <>تأكيد الرمز <KeyRound className="h-4 w-4" /></> : <>دخول إلى المنصة <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-0.5" /></>}</button></div>
      </form>
      <div className="mt-4 grid grid-cols-3 gap-2"><TrustItem icon={<Shield className="h-4 w-4" />} label="RBAC" /><TrustItem icon={<Lock className="h-4 w-4" />} label="Secure" /><TrustItem icon={<Globe2 className="h-4 w-4" />} label="RTL / LTR" /></div><p className="mt-6 text-center text-sm text-muted-foreground">ليس لديك حساب؟ <Link to="/register" className="font-bold text-primary hover:underline">إنشاء حساب جديد</Link></p>
    </div></section>
  </div>
}
function Signal({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="rounded-2xl border border-white/10 bg-white/[.055] p-4 backdrop-blur-xl"><div className="flex items-center gap-2 text-[10px] font-medium text-white/40">{icon}{label}</div><div className="mt-2 text-2xl font-black tracking-tight">{value}</div></div> }
function MiniStatus({ icon, title, value }: { icon: React.ReactNode; title: string; value: string }) { return <div className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[.035] px-4 py-3"><div className="text-white/55">{icon}</div><div><div className="text-[10px] font-bold uppercase tracking-wider text-white/35">{title}</div><div className="mt-0.5 text-xs text-white/60">{value}</div></div></div> }
function TrustItem({ icon, label }: { icon: React.ReactNode; label: string }) { return <div className="flex items-center justify-center gap-2 rounded-xl border bg-muted/30 px-3 py-2.5 text-[10px] font-bold text-muted-foreground">{icon}{label}</div> }
function Field({ label, error, children }: { label: string; error?: string; children: React.ReactNode }) { return <div><label className="mb-2 block text-xs font-bold">{label}</label>{children}{error && <p className="mt-1.5 text-xs font-medium text-destructive">{error}</p>}</div> }
